// Ein Vapi-Assistant pro Stelle: die Stelle wird über die Assistant-ID zugeordnet (REQ-3.6).
// Neue Stelle = neuen Assistant in Vapi anlegen und hier mit seiner ID eintragen.
const JUNIOR_ENTWICKLER = {
  titel: 'Junior Entwickler – Vollzeit (m/w/d)',
  profil: [
    'Unternehmen: Everlast Consulting GmbH, Biberach an der Riß. Berät Unternehmen und setzt KI-Automatisierungen und AI Voice Agents um.',
    'Aufgaben: Automatisierungen mit n8n/Make bauen, Voice Agents (z. B. Vapi) konfigurieren, APIs und Webhooks anbinden, LLM-Prompts entwickeln, an Kundenprojekten mitarbeiten, dokumentieren.',
    'Anforderungen: Grundlagen in JavaScript/TypeScript oder Python, REST-APIs/JSON/Webhooks, Interesse an LLMs/KI, erste Erfahrung mit Automatisierungstools von Vorteil, Git, strukturierte Arbeitsweise, Kommunikationsstärke, sehr gutes Deutsch, Lernbereitschaft, Eigeninitiative.',
    'Level: Junior, Vollzeit. Gehaltsband und Startdatum sind im Profil nicht hinterlegt.',
  ].join('\n'),
};

const STELLEN = {
  // Vapi-Assistant "Everlast Interview - Junior Entwickler"
  '90e79eb0-631e-4186-b1f3-22301718ebf1': JUNIOR_ENTWICKLER,
};

// Demo: genau eine Stelle, deshalb Fallback auf das Junior-Entwickler-Profil.
const stelle = STELLEN[$json.assistantId] ?? JUNIOR_ENTWICKLER;

return { json: { ...$json, stelle: stelle.titel, stellenprofil: stelle.profil } };

